export function getPromptSetByExerciseId(exerciseId: string): GoogleFlowPromptSet | undefined {
  return GOOGLE_FLOW_EXERCISE_PROMPTS.find((item) => item.id === exerciseId);
}

export function getPromptByExerciseId(
  exerciseId: string,
  assetType: GoogleFlowAssetType,
): string | undefined {
  const promptSet = getPromptSetByExerciseId(exerciseId);
  if (!promptSet) return undefined;
  if (assetType === 'storyboard') return promptSet.storyboardPrompt;
  if (assetType === 'hero') return promptSet.heroPrompt;
  return promptSet.muscleCloseupPrompt;
}

export function getAllGoogleFlowJobs() {
  return GOOGLE_FLOW_EXERCISE_PROMPTS.flatMap((exercise) => [
    {
      exerciseId: exercise.id,
      exerciseSlug: exercise.slug,
      exerciseName: exercise.name,
      assetType: 'storyboard' as const,
      prompt: exercise.storyboardPrompt,
      outputFile: exercise.suggestedFiles.storyboard,
      settings: exercise.flowSettings,
    },
    {
      exerciseId: exercise.id,
      exerciseSlug: exercise.slug,
      exerciseName: exercise.name,
      assetType: 'hero' as const,
      prompt: exercise.heroPrompt,
      outputFile: exercise.suggestedFiles.hero,
      settings: exercise.flowSettings,
    },
    {
      exerciseId: exercise.id,
      exerciseSlug: exercise.slug,
      exerciseName: exercise.name,
      assetType: 'muscleCloseup' as const,
      prompt: exercise.muscleCloseupPrompt,
      outputFile: exercise.suggestedFiles.muscleCloseup,
      settings: exercise.flowSettings,
    },
  ]);
}
